<?php require __DIR__.'/bootstrap.php';$token=$_GET['token']??$_POST['token']??'';$done=false;$error='';$row=null;if(preg_match('/^[a-f0-9]{64}$/',$token)){$st=$pdo->prepare('SELECT pr.id,pr.user_id,u.name FROM password_reset_tokens pr JOIN users u ON u.id=pr.user_id WHERE pr.token_hash=? AND pr.used_at IS NULL AND pr.expires_at>NOW() LIMIT 1');$st->execute([hash('sha256',$token)]);$row=$st->fetch();}
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();if(!$row)$error='Este link é inválido ou expirou.';elseif(strlen($_POST['password']??'')<12)$error='A senha deve ter pelo menos 12 caracteres.';elseif($_POST['password']!==($_POST['confirm']??''))$error='As senhas não conferem.';else{$pdo->beginTransaction();$pdo->prepare('UPDATE users SET password_hash=? WHERE id=?')->execute([password_hash($_POST['password'],PASSWORD_DEFAULT),$row['user_id']]);$pdo->prepare('UPDATE password_reset_tokens SET used_at=NOW() WHERE id=?')->execute([$row['id']]);$pdo->commit();audit('password_reset_completed','user',(int)$row['user_id']);$done=true;}}
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Nova senha | Newsiga</title><link rel="stylesheet" href="assets/style.css"></head><body class="login-bg"><main class="login-card"><a class="brand" href="/">newsiga</a><p class="kicker">SEGURANÇA</p><h1>Crie sua nova senha</h1><?php if($done):?><p class="success">Senha alterada com sucesso. Seu acesso já está liberado.</p><a class="button secondary-link" href="<?=url()?>">Entrar no portal</a><?php elseif(!$row):?><p class="error">Este link é inválido ou expirou. Solicite um novo link.</p><a class="button secondary-link" href="<?=url('esqueci-a-senha.php')?>">Solicitar novo link</a><?php else:?><?php if($error):?><p class="error"><?=e($error)?></p><?php endif;?><p>Use pelo menos 12 caracteres.</p><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="token" value="<?=e($token)?>"><label>Nova senha<input name="password" type="password" minlength="12" required autocomplete="new-password"></label><label>Confirmar senha<input name="confirm" type="password" minlength="12" required autocomplete="new-password"></label><button class="button">Salvar nova senha</button></form><?php endif;?></main></body></html>
